UPDATE property_comment
SET content = #{content}
WHERE property_id = #{propertyId}
  AND comment_id = #{commentId}
  AND user_id = #{userId}
  AND del_yn = 'N'

UPDATE property_comment
SET del_yn = 'Y'
WHERE property_id = #{propertyId}
  AND comment_id = #{commentId}
  AND user_id = #{userId}
  AND del_yn = 'N'
